def validate_ProjectRequest(value: ProjectRequest) -> None:
    from .scene import validate_ModelSetup as validate_ModelSetup
    if isinstance(value, ProjectRequestDiagnose):
        pass
    elif isinstance(value, ProjectRequestImport):
        if not isinstance(value.path, str):
            raise ValueError("Expected string")
        validate_ImportFormat(value.format)
        if not isinstance(value.textures, tuple):
            raise TypeError("Expected an immutable tuple")
        for v0 in value.textures:
            validate_TextureSlot(v0)
    elif isinstance(value, ProjectRequestOpen):
        if not isinstance(value.path, str):
            raise ValueError("Expected string")
    elif isinstance(value, ProjectRequestNew):
        if not isinstance(value.document_id, str):
            raise ValueError("Expected string")
        validate_ModelSetup(value.setup)
    elif isinstance(value, ProjectRequestExport):
        if not isinstance(value.path, str):
            raise ValueError("Expected string")
        validate_ExportFormat(value.format)
        if not isinstance(value.name, str):
            raise ValueError("Expected string")
        if value.object_id is not None:
            if not isinstance(value.object_id, str):
                raise ValueError("Expected string")
        if type(value.allow_loss) is not bool:
            raise ValueError("Expected bool")
        if type(value.bake_animation) is not bool:
            raise ValueError("Expected bool")
        if type(value.auto_frame_rate) is not bool:
            raise ValueError("Expected bool")
    else:
        raise TypeError("Expected ProjectRequest")

def encode_ProjectRequest(value: ProjectRequest) -> object:
    from .scene import encode_ModelSetup as encode_ModelSetup
    if isinstance(value, ProjectRequestDiagnose):
        return {'kind': 'diagnose', **cast(Mapping[str, object], {})}
    elif isinstance(value, ProjectRequestImport):
        return {'kind': 'import', **cast(Mapping[str, object], {'path': value.path, 'format': encode_ImportFormat(value.format), 'textures': [encode_TextureSlot(v0) for v0 in value.textures]})}
    elif isinstance(value, ProjectRequestOpen):
        return {'kind': 'open', **cast(Mapping[str, object], {'path': value.path})}
    elif isinstance(value, ProjectRequestNew):
        return {'kind': 'new', **cast(Mapping[str, object], {'document_id': value.document_id, 'setup': encode_ModelSetup(value.setup)})}
    elif isinstance(value, ProjectRequestExport):
        return {'kind': 'export', **cast(Mapping[str, object], {'path': value.path, 'format': encode_ExportFormat(value.format), 'name': value.name, 'object_id': None if value.object_id is None else value.object_id, 'allow_loss': value.allow_loss, 'bake_animation': value.bake_animation, 'auto_frame_rate': value.auto_frame_rate})}
    raise TypeError("Expected ProjectRequest")

def read_ProjectRequest(value: object) -> ProjectRequest:
    from .scene import read_ModelSetup as read_ModelSetup
    if isinstance(value, (ProjectRequestDiagnose, ProjectRequestImport, ProjectRequestOpen, ProjectRequestNew, ProjectRequestExport,)): return value
    r = record(value)
    tag = string(r['kind'])
    if tag == 'diagnose':
        return ProjectRequestDiagnose()
    elif tag == 'import':
        f = record(r)
        return ProjectRequestImport(path=string(f['path']), format=read_ImportFormat(f['format']), textures=tuple(read_TextureSlot(v0) for v0 in sequence(f['textures'])))
    elif tag == 'open':
        f = record(r)
        return ProjectRequestOpen(path=string(f['path']))
    elif tag == 'new':
        f = record(r)
        return ProjectRequestNew(document_id=string(f['document_id']), setup=read_ModelSetup(f['setup']))
    elif tag == 'export':
        f = record(r)
        return ProjectRequestExport(path=string(f['path']), format=read_ExportFormat(f['format']), name=string(f['name']), object_id=None if f.get('object_id', None) is None else string(f.get('object_id', None)), allow_loss=_boolean(f['allow_loss']), bake_animation=_boolean(f['bake_animation']), auto_frame_rate=_boolean(f['auto_frame_rate']))
    raise ValueError("Unknown ProjectRequest variant")

